const int qtd_comandos = (int)(sizeof comandos / sizeof comandos[0]);

const comando_t *achar_comando(const char *nome)
{
    for (int i = 0; i < qtd_comandos; i++)
        if (compara_texto(comandos[i].nome, nome) == 0 ||
            (comandos[i].apelido && compara_texto(comandos[i].apelido, nome) == 0))
            return &comandos[i];
    return NULL;
}

static void sai(const char *s) { escrever_saida(SAIDA, s, (int)tam_texto(s)); }

/* Títulos de la ayuda en negrita cian si la salida es un terminal con colores (D263). */
static void titulo(const char *s)
{
    bool cor = sh_cor() && eh_terminal(SAIDA);
    if (cor) sai("\x1b[1;36m");
    sai(s);
    if (cor) sai("\x1b[0m");
}

static const char *ajuda_sh =
    "El lenguaje de sagsh (como sh/bash):\n"
    "  a; b   a && b   a || b   a | b   a &   ( subshell )   { grupo; }   # comentario\n"
    "  'literal'  \"con $VAR\"  \\x   VAR=valor  $VAR ${VAR:-defecto} ${#VAR} ${VAR%.txt}\n"
    "  $? $$ $! $# $1..$9 $@ $*   $(orden) `orden`   $((1 + 2 * x))   ~   * ? [abc]\n"
    "  > a  >> a  < a  2> e  2>&1  &> a  <<FIN (here-doc)  <<< texto\n"
    "  if orden; then ...; elif ...; else ...; fi     while orden; do ...; done\n"
    "  until orden; do ...; done   for x in a b c; do ...; done   break  continue\n"
    "  case $x in a|b) ...;; *.txt) ...;; *) ...;; esac\n"
    "  nombre() { local v=1; echo $1; return 0; }\n"
    "Scripts: sagsh script.sh args, o un archivo que empiece por #!/bin/sh (ejemplos en /ejemplos).\n"
    "Prompt: variable PS1 con escapes de bash: \\u usuario, \\h máquina, \\w carpeta, \\$ ($ o # si eres root),\n"
    "  \\e[32m colores (\\[ y \\] se aceptan). Inicio: /etc/sagshrc. NO_COLOR desactiva los colores.\n"
    "ajuda internos: lista los internos.\n";

/* Atajos del escritorio (D119): los atrapa el gestor de ventanas del kernel. */
static const char *ajuda_atajos =
    "Atajos del escritorio:\n"
    "  Alt+Tab          cambia de ventana (con Alt apretada, cada Tab avanza)\n"
    "  Alt+Mayús+Tab    lo mismo hacia atrás; Esc cancela\n"
    "  Alt+F4           cierra la ventana activa (como la X: pregunta si guarda)\n"
    "  Windows          (sola) abre o cierra el menú Inicio; también Ctrl+Esc\n"
    "  Windows+D        minimiza todo y muestra el escritorio; otra vez, lo restaura\n"
    "  Ctrl+Alt+Supr    Administrador de tareas (también Ctrl+Mayús+Esc)\n"
    "  F11              pantalla completa (si el programa la admite); Esc sale\n"
    "Más en /ayuda/atajos.md.\n";

static const char *ajuda_internos =
    "Comandos internos de sagsh:\n"
    "  cd pwd echo printf read test [ true false : exit return break continue shift\n"
    "  export unset set readonly local env(programa) alias unalias type command\n"
    "  source . eval let exec trap(EXIT) history jobs wait fg bg kill clear ajuda\n"
    "  set -e (sale al primer error)  set -u (variable sin definir es error)  set -x (traza)\n"
    "  set -f (sin comodines)  set -- a b (cambia $1 $2)\n";

int interno_ajuda(int argc, char **argv)
{
    if (argc > 1) {
        if (compara_texto(argv[1], "sh") == 0 || compara_texto(argv[1], "sagsh") == 0 ||
            compara_texto(argv[1], "shell") == 0) { titulo("El lenguaje de sagsh (como sh/bash):\n"); sai(ajuda_sh + 37); return 0; }
        if (compara_texto(argv[1], "internos") == 0) { sai(ajuda_internos); return 0; }
        if (compara_texto(argv[1], "atajos") == 0 || compara_texto(argv[1], "teclas") == 0) { sai(ajuda_atajos); return 0; }
        const comando_t *c = achar_comando(argv[1]);
        if (!c) {
            if (interno_achar(argv[1])) { imprimir("%s: comando interno del shell (ajuda internos)\n", argv[1]); return 0; }
            imprimir("ajuda: no conozco el comando %s\n", argv[1]);
            return 1;
        }
        titulo("Uso:");
        imprimir(" %s\n%s\n", c->uso, c->explicacao);
        if (c->apelido) imprimir("Alias en portugués: %s\n", c->apelido);
        imprimir("Tipo: %s\n", c->interno ? "comando interno del shell" : "programa en /bin");
        return 0;
    }
    titulo("Comandos de SaguiOS (nombre/alias):\n");
    for (int i = 0; i < qtd_comandos; i++) {
        char nome[32];
        formatar_texto(nome, sizeof nome, "%s%s%s", comandos[i].nome, comandos[i].apelido ? "/" : "",
                       comandos[i].apelido ? comandos[i].apelido : "");
        /* Dos columnas de 39 caracteres: la línea nunca llega a 80 (la pantalla
         * saltaría una línea de más). */
        imprimir("  %-20s%-17s%s", nome, comandos[i].curta, (i % 2 == 1 || i == qtd_comandos - 1) ? "\n" : "");
    }
    sai("Archivo: cmd > a, >> a, < a, 2>&1   Pipe: cmd1 | cmd2   Segundo plano: cmd &\n");
    sai("Shell: variables, if/for/while/case, funciones, $(...): ajuda sh   Internos: ajuda internos\n");
    sai("ajuda <comando> explica un comando. Flechas: historial. Tab: completa nombres.\n");
    sai("Escritorio: Alt+Tab, Alt+F4, Windows, Windows+D, Ctrl+Alt+Supr: ajuda atajos\n");
    return 0;
}
